window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-c209db82fa8ac509"]={"versions": [{"id": "FIG-c209db82fa8ac509", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation eines Entwurfsmusters (Pattern Specification) im AUTOSAR Generic Structure Template (TPS GenericStructureTemplate). Es veranschaulicht die modellgetriebene Transformation von Variationspunkten, indem eine kompakte Darstellung im annotierten Metamodell (<code>annotated meta model</code>) der resultierenden Struktur im erweiterten Metamodell (<code>extended meta model</code>) über eine «generates»-Beziehung gegenübergestellt wird.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm gliedert sich in zwei Hauptbereiche:</p>\n<ul class=\"fig-list\"><li><strong>annotated meta model</strong>:\n<ul class=\"fig-list\"><li>Platzhalter-Klasse <code>{WholeClass}</code> als Aggregat-Wurzel.\n</li><li>Platzhalter-Klasse <code>{PartClass}</code>.\n</li><li>Kompositionsbeziehung von <code>{WholeClass}</code> zu <code>{PartClass}</code> mit der Rollenbezeichnung <code>+{partRole}</code> und dem Stereotyp <code>«atpVariation»</code>.\n</li><li>Angeheftete Notiz an der Assoziation: <code>Vh.latestBindingTime = {latestBindingTime}</code>.\n</li></ul>\n</li><li><strong>extended meta model</strong>:\n<ul class=\"fig-list\"><li><code>{WholeClass}</code>: Enthält im Attribut-/Constraint-Bereich die OCL-Bedingung <code>constraints {{PartRole}.variationPoint.bindingTime &lt;= {latestBindingTime}}</code>.\n</li><li><code>{PartClass}Conditional</code>: Repräsentiert die bedingte Hülle des variablen Elements und ist per Komposition (<code>+{partRole} *</code>) unter <code>{WholeClass}</code> eingebunden.\n</li><li><code>VariationPoint</code>: Besitzt das Attribut <code>- bindingTime: BindingTimeEnum</code> und ist per Komposition (<code>+variationPoint 1</code>) an <code>{PartClass}Conditional</code> gebunden.\n</li><li><code>{PartClass}</code>: Reale Zielklasse, eingebunden über eine Komposition mit Rolle <code>+the{PartClass} 1</code> unter <code>{PartClass}Conditional</code>.\n</li></ul>\n</li><li><strong>Transformationsbeziehung</strong>:\n<ul class=\"fig-list\"><li>Eine gestrichelte gerichtete Abhängigkeitspfeillinie mit dem Stereotyp <code>«generates»</code> verbindet das <code>annotated meta model</code> mit dem <code>extended meta model</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm beschreibt ein strukturelles Metamodell-Muster ohne zeitlichen Ablauf oder Interaktionssequenzen. Dynamisch relevant ist der generative Mappingschritt: Eine mit <code>«atpVariation»</code> und <code>Vh.latestBindingTime</code> annotierte Komposition zwischen <code>{WholeClass}</code> und <code>{PartClass}</code> wird in eine intermediäre <code>{PartClass}Conditional</code>-Klasse expandiert, welche die Zielinstanz <code>{PartClass}</code> kapselt, einen <code>VariationPoint</code> zur Auswertung des Bindungszeitpunkts zuordnet und die Konsistenz über eine Invariante (<code>constraints</code>) absichert.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normatives Spezifikationsmuster für die Definition von AUTOSAR-Variabilität auf Metamodellebene. Modellierer und Werkzeugentwickler müssen sicherstellen, dass bei Verwendung des Stereotyps <code>«atpVariation»</code> an einer Assoziation die Bindungszeit des Variationspunkts (<code>bindingTime</code>) den durch <code>{latestBindingTime}</code> spezifizierten Bindungszeitpunkt nicht überschreitet (<code>&lt;=</code>). Bei der Metamodell-Instanziierung und Code-/Schema-Generierung fungiert <code>{PartClass}Conditional</code> als generierter Träger der Variationspunkt-Semantik.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-d50582914f4413bb", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation eines Entwurfsmusters (Pattern Specification) im AUTOSAR Generic Structure Template (TPS GenericStructureTemplate). Es veranschaulicht die modellgetriebene Transformation von Variationspunkten, indem eine kompakte Darstellung im annotierten Metamodell (<code>annotated meta model</code>) der resultierenden Struktur im erweiterten Metamodell (<code>extended meta model</code>) über eine «generates»-Beziehung gegenübergestellt wird.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm gliedert sich in zwei Hauptbereiche:</p>\n<ul class=\"fig-list\"><li><strong>annotated meta model</strong>:\n<ul class=\"fig-list\"><li>Platzhalter-Klasse <code>{WholeClass}</code> als Aggregat-Wurzel.\n</li><li>Platzhalter-Klasse <code>{PartClass}</code>.\n</li><li>Kompositionsbeziehung von <code>{WholeClass}</code> zu <code>{PartClass}</code> mit der Rollenbezeichnung <code>+{partRole}</code> und dem Stereotyp <code>«atpVariation»</code>.\n</li><li>Angeheftete Notiz an der Assoziation: <code>vh.latestBindingTime = {latestBindingTime}</code>.\n</li></ul>\n</li><li><strong>extended meta model</strong>:\n<ul class=\"fig-list\"><li><code>{WholeClass}</code>: Enthält im Attribut-/Constraint-Bereich die OCL-Bedingung <code>constraints {{PartRole}.variationPoint.bindingTime &lt;= {latestBindingTime}}</code>.\n</li><li><code>{PartClass}Conditional</code>: Repräsentiert die bedingte Hülle des variablen Elements und ist per Komposition (<code>+{partRole} *</code>) unter <code>{WholeClass}</code> eingebunden.\n</li><li><code>VariationPoint</code>: Besitzt das Attribut <code>- bindingTime :BindingTimeEnum</code> und ist per Komposition (<code>+variationPoint 1</code>) an <code>{PartClass}Conditional</code> gebunden.\n</li><li><code>{PartClass}</code>: Reale Zielklasse, eingebunden über eine Komposition mit Rolle <code>+the{PartClass} 1</code> unter <code>{PartClass}Conditional</code>.\n</li></ul>\n</li><li><strong>Transformationsbeziehung</strong>:\n<ul class=\"fig-list\"><li>Eine gestrichelte gerichtete Abhängigkeitspfeillinie mit dem Stereotyp <code>«generates»</code> verbindet das <code>annotated meta model</code> mit dem <code>extended meta model</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm beschreibt ein strukturelles Metamodell-Muster ohne zeitlichen Ablauf oder Interaktionssequenzen. Dynamisch relevant ist der generative Mappingschritt: Eine mit <code>«atpVariation»</code> und <code>Vh.latestBindingTime</code> annotierte Komposition zwischen <code>{WholeClass}</code> und <code>{PartClass}</code> wird in eine intermediäre <code>{PartClass}Conditional</code>-Klasse expandiert, welche die Zielinstanz <code>{PartClass}</code> kapselt, einen <code>VariationPoint</code> zur Auswertung des Bindungszeitpunkts zuordnet und die Konsistenz über eine Invariante (<code>constraints</code>) absichert.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normatives Spezifikationsmuster für die Definition von AUTOSAR-Variabilität auf Metamodellebene. Modellierer und Werkzeugentwickler müssen sicherstellen, dass bei Verwendung des Stereotyps <code>«atpVariation»</code> an einer Assoziation die Bindungszeit des Variationspunkts (<code>bindingTime</code>) den durch <code>{latestBindingTime}</code> spezifizierten Bindungszeitpunkt nicht überschreitet (<code>&lt;=</code>). Bei der Metamodell-Instanziierung und Code-/Schema-Generierung fungiert <code>{PartClass}Conditional</code> als generierter Träger der Variationspunkt-Semantik.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-c209db82fa8ac509", "to": "FIG-d50582914f4413bb", "fr": "R4.0.3", "tr": "R4.1.3", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>In der Kommentar-Notiz zur Assoziation im Paket <code>annotated meta model</code> wurde die Schreibweise des Attributs von <code>Vh.latestBindingTime</code> zu <code>vh.latestBindingTime</code> (Kleinschreibung des Präfixes) korrigiert.\n</li></ul>"}]};
